CORE = ['Why read','Business','Revenue model','Products','Customers','Moat','Capacity','Capex tracker','Management: who they are','Management: skin in the game','Management: capital allocation','Management: delivery record','Management: communication','Management: fairness to minorities','Management: red flags','Current guidance','Next-quarter outlook','Future growth build','Trigger table','Peers','Reality vs optionality','Causal chain','Cash and earnings quality','Governance','Risk cards with signals','Anti-thesis','Valuation','Assumed vs grounded']
WHERE = ['S1','S2','S2','S3','S5','S6','S9','S9','S10','S10','S10','S10, S11','S10, S11','S10, S18','S10, S18','S12','S12','S13','S1, S13','S14','S15','S16','S17','S18','S19','S19','S20 and section 5','S20 and section 6']
V['COVERAGE_MAP'] = '\n'.join(f'| {a} | {b} |' for a,b in zip(CORE,WHERE))

def build(dynamic, design):
    values = {**V, **dynamic}
    skeleton = (SKILL/'assets/skeleton.txt').read_text(encoding='utf-8')
    skeleton = skeleton.replace('Lead analyst: Claude Opus 5.5 as a senior equity research analyst; Sonnet 5.5 workers read the documents', 'Lead analyst: the current capable research lead; GPT-6.1 Sol workers with low reasoning effort read documents and verify evidence')
    skeleton = skeleton.replace('Sonnet 5.5 workers', 'GPT-6.1 Sol workers with low reasoning effort').replace('Opus does not', 'The lead does not').replace('Opus answers', 'The lead answers')
    skeleton = skeleton.replace('Models: GPT-6.1 Sol workers with low reasoning effort read (pass model "sonnet" on every worker call). Opus 5.5 decides, writes and checks. If Sonnet 5.5 is unavailable, stop and say so; never fall back to a smaller model.', 'Models: all document readers, financial scanners and evidence verifiers use model="gpt-6.1-sol", reasoning_effort="low", fork_turns="none". Supply complete task context and record actual settings. The lead diagnoses, writes and checks. Report a model failure rather than silently substituting.')
    def replace(match):
        name = match.group(1).split(':',1)[0]
        return match.group(0) if name == 'INCLUDE' else values[name]
    filled = re.sub(r'\{\{([^}]+)\}\}', replace, skeleton)
    filled = filled.replace('A RED management verdict caps the rating at HOLD.', 'A RED management verdict caps the rating at HOLD. If required guidance or reliable value inputs are absent, report NOT RATED with the reason; do not manufacture a rating.')
    # The source template contains a legacy encoding artifact for the rupee sign.
    filled = filled.replace('\u00e2\u201a\u00b9', 'INR ')
    for char in '\u2012\u2013\u2014\u2015':
        filled = filled.replace(char,'-')
    (ROOT/'prompt-draft.md').write_text(filled,encoding='utf-8')
    (ROOT/'prompt-slots.json').write_text(json.dumps(design,indent=2,ensure_ascii=False),encoding='utf-8')

if __name__ == '__main__':
    dynamic = json.loads((ROOT/'company-slots.json').read_text(encoding='utf-8'))
    design = json.loads((ROOT/'design-slots.json').read_text(encoding='utf-8'))
    build(dynamic,design)
